stage_a_raw:
{
  "decisions": [
    {
      "decision": "startup_variable_domain",
      "evidence": "\"The number of generators and startup decisions must be integers.\"",
      "options": [
        "s binary (0/1 per type-period)",
        "s NonNegativeIntegers bounded by max_op",
        "s NonNegativeReals"
      ],
      "plausibility": [
        0.45,
        0.45,
        0.1
      ],
      "majority_option": "s binary (0/1 per type-period)"
    },
    {
      "decision": "startup_logic_at_first_period",
      "evidence": "\"the number of operational generators in any period cannot exceed the number from the previous period plus the number started in the current period\"",
      "options": [
        "include n[g,0] <= s[g,0] for the first period",
        "skip the startup constraint at t=0 (no previous period)"
      ],
      "plausibility": [
        0.5,
        0.5
      ],
      "majority_option": "skip the startup constraint at t=0 (no previous period)"
    },
    {
      "decision": "power_variable_aggregation",
      "evidence": "\"Each Type 0 generator can produce between 34 MW and 127 MW\"",
      "options": [
        "p[g,t] is total output of type g, bounded by pmin*n <= p <= pmax*n",
        "p[g,t] is per-generator output with separate unit-level variables"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "p[g,t] is total output of type g, bounded by pmin*n <= p <= pmax*n"
    },
    {
      "decision": "reserve_margin_uses_capacity_or_output",
      "evidence": "\"The total maximum power output of all generators in each period must be at least 15% higher than the demand for that period\"",
      "options": [
        "sum(pmax[g]*n[g,t]) >= 1.15*demand[t]",
        "sum(p[g,t]) >= 1.15*demand[t]"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "sum(pmax[g]*n[g,t]) >= 1.15*demand[t]"
    },
    {
      "decision": "demand_constraint_direction",
      "evidence": "\"The system must meet the following demand in each period\"",
      "options": [
        "sum(p[g,t]) >= demand[t]",
        "sum(p[g,t]) = demand[t]"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "sum(p[g,t]) >= demand[t]"
    },
    {
      "decision": "objective_components_scope",
      "evidence": "\"Minimize the total operational cost ... fixed base cost of 80 units per generator per period, a power generation cost of 4 units per MW produced, and startup costs\"",
      "options": [
        "base_cost*n + power_cost*p + startup_cost*s over all g,t",
        "base_cost*n + power_cost*p + startup_cost*s but startup only when n increases"
      ],
      "plausibility": [
        0.8,
        0.2
      ],
      "majority_option": "base_cost*n + power_cost*p + startup_cost*s over all g,t"
    }
  ]
}
